def count_unsorted_permutations(n, sequence):
    MOD = 10**9 + 9

    def factorial(x):
        if x == 0 or x == 1:
            return 1
        f = 1
        for i in range(2, x + 1):
            f = (f * i) % MOD
        return f

    def mod_inverse(a, p):
        return pow(a, p - 2, p)

    def count_inversions(arr):
        def merge_count_split_inv(arr, temp_arr, left, mid, right):
            i = left    # Starting index for left subarray
            j = mid + 1 # Starting index for right subarray
            k = left    # Starting index to be sorted
            inv_count = 0

            while i <= mid and j <= right:
                if arr[i] <= arr[j]:
                    temp_arr[k] = arr[i]
                    i += 1
                else:
                    temp_arr[k] = arr[j]
                    inv_count += (mid-i + 1)
                    j += 1
                k += 1

            while i <= mid:
                temp_arr[k] = arr[i]
                i += 1
                k += 1

            while j <= right:
                temp_arr[k] = arr[j]
                j += 1
                k += 1

            for i in range(left, right + 1):
                arr[i] = temp_arr[i]

            return inv_count

        def merge_sort_and_count(arr, temp_arr, left, right):
            inv_count = 0
            if left < right:
                mid = (left + right) // 2

                inv_count += merge_sort_and_count(arr, temp_arr, left, mid)
                inv_count += merge_sort_and_count(arr, temp_arr, mid + 1, right)
                inv_count += merge_count_split_inv(arr, temp_arr, left, mid, right)

            return inv_count

        temp_arr = [0] * n
        return merge_sort_and_count(arr, temp_arr, 0, n - 1)

    total_permutations = factorial(n)
    inversions = count_inversions(sequence)

    sorted_permutations = pow(2, inversions, MOD)
    unsorted_permutations = (total_permutations - sorted_permutations + MOD) % MOD

    return unsorted_permutations

