def count_unsorted_permutations(n, sequence):
    MOD = 10**9 + 9

    def factorial(x):
        if x == 0 or x == 1:
            return 1
        result = 1
        for i in range(2, x + 1):
            result = (result * i) % MOD
        return result

    def mod_inverse(x, mod):
        return pow(x, mod - 2, mod)

    def count_sorted_permutations(seq):
        from collections import Counter
        freq = Counter(seq)
        total_permutations = factorial(len(seq))
        for count in freq.values():
            total_permutations = (total_permutations * mod_inverse(factorial(count), MOD)) % MOD
        return total_permutations

    sorted_permutations = count_sorted_permutations(sequence)
    total_permutations = factorial(n)
    unsorted_permutations = (total_permutations - sorted_permutations + MOD) % MOD

    return unsorted_permutations

